window.JANE_DATA = {"levels": [{"num": "01", "cat": "Percepción", "name": "Observación y Objetividad Crítica", "objective": "instalar el filtro de objetividad — separar el hecho observable del juicio automático — antes de tocar cualquier técnica de lectura de personas.", "sources": ["El cuerpo habla — Joe Navarro (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">1 — Mentalismo (NotebookLM, presentación)</a>", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">The Mentalist Code (NotebookLM, presentación — fuente: YouTube)</a>"], "sessions": [{"id": "day-n1-s1d1", "label": "Sesión 1", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Presentación The Mentalist Code (introducción)", "html": "Presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">The Mentalist Code</a></em> (introducción)"}, {"tag": "Ver", "text": "Presentación 1 – Mentalismo + tabla del Filtro de Objetividad (sección 00)", "html": "Presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">1 – Mentalismo</a></em> + tabla del Filtro de Objetividad (sección 00)"}, {"tag": "Hacer", "text": "Anota 3 ejemplos propios de \"juicio subjetivo → hecho objetivo\" en tu libreta.", "html": "Anota 3 ejemplos propios de \"juicio subjetivo → hecho objetivo\" en tu libreta."}], "duracion": "<strong>The Mentalist Code:</strong> ~5 min · <strong>1 – Mentalismo:</strong> ~15 min · <strong>Anotar:</strong> ~15 min", "como": "Mira las dos presentaciones seguidas sin pausar a tomar notas; luego, con la tabla del Filtro de Objetividad delante, escribe tus 3 ejemplos. Es trabajo de escritorio — no necesitas observar a nadie en vivo todavía.", "memoria": "Elige tu primer espacio real (tu habitación u otro lugar muy conocido) y fija un recorrido con 10 puntos concretos (loci) en orden lógico."}, {"id": "day-n1-s1d2", "label": "Sesión 2", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Anota 20 hechos objetivos sobre 2 personas distintas de un vídeo, cero adjetivos.", "html": "Anota 20 hechos objetivos sobre 2 personas distintas de un vídeo, cero adjetivos."}], "duracion": "~60 min — puedes hacerlo de una sentada o repartido en 2-3 tandas si te cansas", "como": "No hace falta hablar con nadie: usa dos entrevistas largas donde salga una persona que no conozcas de nada — por ejemplo un episodio de <a href=\"https://www.youtube.com/@FirstWeFeast\" rel=\"noopener\" target=\"_blank\">Hot Ones (First We Feast)</a>, o busca en YouTube <strong>\"entrevista larga completa\"</strong> / <strong>\"long form interview\"</strong> y elige cualquiera. Pausa cada 15-20 segundos y ve anotando, repartido en estas categorías para no quedarte en blanco:<br/>· Ropa (tipo, color, estado de uso)<br/>· Calzado<br/>· Accesorios (reloj, anillos, gafas, joyas)<br/>· Pelo (largo, color, peinado)<br/>· Postura corporal<br/>· Gestos habituales de manos<br/>· Tono y ritmo de voz (no lo que dice, cómo lo dice)<br/>· Objetos visibles alrededor<br/>Prueba del hecho objetivo: si no se puede fotografiar o grabar, es una interpretación tuya — descártalo.", "memoria": "Repite el recorrido de memoria, sin objetos: nombra los 10 loci en orden hasta que no dudes en ninguno."}, {"id": "day-n1-s2d1", "label": "Sesión 3", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Ver", "text": "Repasa en la presentación 1 – Mentalismo la parte del escaneo por zonas", "html": "Repasa en la presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">1 – Mentalismo</a></em> la parte del escaneo por zonas"}, {"tag": "Hacer", "text": "Anota las 5 zonas del cuerpo del barrido sistemático, en orden.", "html": "Anota las 5 zonas del cuerpo del barrido sistemático, en orden."}], "duracion": "<strong>Ver:</strong> ~5 min · <strong>Anotar:</strong> ~5 min (si vas más rápido, no pasa nada — usa el resto del bloque para adelantar mañana o repetir el escaneo varias veces hasta automatizarlo)", "como": "Solo el tramo sobre el barrido por zonas, no hace falta repetir la presentación entera. Anota las 5 zonas como chuleta para consultar mañana.", "memoria": "Aprende la técnica de la imagen vívida: coloca una lista de 5 objetos cotidianos en tus primeros 5 loci con imágenes exageradas o absurdas."}, {"id": "day-n1-s2d2", "label": "Sesión 4", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Escaneo de 6 segundos con 5 personas de una cámara de calle en directo. Anota resultados.", "html": "Escaneo de 6 segundos con 5 personas de una cámara de calle en directo. Anota resultados."}], "duracion": "~30 min de una sentada", "como": "Usa la cámara en directo del canal de <a href=\"https://www.youtube.com/@earthcam\" rel=\"noopener\" target=\"_blank\">EarthCam</a> — tienen varias plazas del mundo emitiendo 24h (Times Square es la más concurrida), o busca <strong>\"live street cam\"</strong> en YouTube si prefieres otra ciudad. Pausa en una persona nueva cada vez, haz tu escaneo de 6 segundos siguiendo las 5 zonas que anotaste en la Sesión 3 (una detrás de otra, en el mismo orden siempre), anota 1 dato por zona, siguiente persona — sin hablar con nadie.", "memoria": "Recupera esos 5 objetos en orden recorriendo los loci de memoria, sin mirar la lista."}, {"id": "day-n1-s3d1", "label": "Sesión 5", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Ver", "text": "Relee en la tabla de la sección 00 la fila \"zapatos con desgaste\"", "html": "Relee en la tabla de la sección 00 la fila \"zapatos con desgaste\""}, {"tag": "Hacer", "text": "Elige y prepara una bandeja de 15 objetos para el Kim's Game de mañana.", "html": "Elige y prepara una bandeja de 15 objetos para el Kim's Game de mañana."}], "duracion": "<strong>Ver:</strong> ~3 min · <strong>Preparar bandeja:</strong> ~15 min", "como": "Reúne 15 objetos pequeños de tu propia habitación (bolígrafos, llaves, monedas, cargadores...) en una bandeja o caja — no necesitas comprar nada.", "memoria": "Amplía a los 10 loci completos con una lista nueva de 10 objetos, una imagen por locus."}, {"id": "day-n1-s3d2", "label": "Sesión 6", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Kim's Game: memoriza 15 objetos 60s y recítalos; deduce 1 hecho de un objeto ajeno real.", "html": "Kim's Game: memoriza 15 objetos 60s y recítalos; deduce 1 hecho de un objeto ajeno real."}], "duracion": "~30 min (el ejercicio es corto — repítelo 2-3 veces con objetos distintos)", "como": "Cronometra 60s mirando la bandeja, tápala y escribe la lista de memoria. Cambia el orden o algunos objetos entre repeticiones para no memorizar la lista en vez del objeto.", "memoria": "Recita los 10 objetos en orden y, si te sale, también en orden inverso."}, {"id": "day-n1-s4d1", "label": "Sesión 7", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Repasa una sección de 1 – Mentalismo que aún no hayas revisado", "html": "Repasa una sección de <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">1 – Mentalismo</a></em> que aún no hayas revisado"}, {"tag": "Hacer", "text": "Relee tus notas de las sesiones anteriores. Elige el vídeo mudo que vas a narrar mañana.", "html": "Relee tus notas de las sesiones anteriores. Elige el vídeo mudo que vas a narrar mañana."}], "duracion": "<strong>Ver:</strong> ~20 min · <strong>Elegir vídeo + releer notas:</strong> ~15 min", "como": "El \"vídeo mudo\" de mañana puede ser cualquier entrevista que no hayas visto ya — por ejemplo un episodio de <a href=\"https://www.youtube.com/@FirstWeFeast\" rel=\"noopener\" target=\"_blank\">Hot Ones</a> u otro programa de entrevistas, o busca <strong>\"entrevista completa\"</strong> en YouTube. Elige uno de al menos 5 minutos y siléncialo tú mismo desde el móvil, no hace falta buscar uno especial.", "memoria": "Repite el ejercicio con una lista nueva de 10 objetos para llegar entrenado a la prueba de hito."}, {"id": "day-n1-s4d2", "label": "Sesión 8", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Graba 10s narrando la observación pura de tu vídeo mudo. Revisa 0% de juicio subjetivo. Hito de nivel.", "html": "Graba 10s narrando la observación pura de tu vídeo mudo. Revisa 0% de juicio subjetivo. Hito de nivel."}], "duracion": "~20 min (grabar + revisar) — usa el resto del bloque para repetirlo si no sale a la primera", "como": "Usa la cámara del móvil en modo selfie, o solo grabación de voz mientras miras la pantalla. Narra solo lo que ves, nunca lo que \"parece sentir\" o \"está pensando\": expresión facial general, postura, gestos de manos, ropa, entorno. Si te oyes decir \"parece que\", \"se nota que\" o \"está claro que\", eso es juicio, no observación — para y reformula esa frase como un hecho. No necesitas subirlo a ningún sitio, es solo para autoevaluarte.", "memoria": "<strong>Hito (tras la sesión 8):</strong> memoriza 10 elementos y recítalos en orden sin fallos, cronometrado."}], "checklist": ["Completo 20 hechos objetivos/día durante 5 días seguidos sin recaer en adjetivos", "Hago el barrido de 6 segundos de forma automática, sin recordármelo antes", "Supero el Kim's Game con 15/15 objetos en dos intentos distintos"], "milestone": "listar 5 hechos objetivos de una persona real en 10 segundos, sin ningún juicio subjetivo mezclado.", "simcards": []}, {"num": "02", "cat": "Comunicación", "name": "Lenguaje No Verbal y Estrés Límbico", "objective": "decodificar el sistema límbico — identificar respuestas de estrés y comportamiento pacificador antes de juzgar el rostro.", "sources": ["El cuerpo habla — Joe Navarro (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">2 — Mentalismo (NotebookLM, vídeo 8:17)</a>"], "sessions": [{"id": "day-n2-s1d1", "label": "Sesión 9", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Vídeo 2 – Mentalismo (8:17) + capítulo de \"El cuerpo habla\" sobre piernas y pies", "html": "Vídeo <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">2 – Mentalismo</a></em> (8:17) + capítulo de \"El cuerpo habla\" sobre piernas y pies"}, {"tag": "Hacer", "text": "Anota 3 señales de sinceridad y 3 de incomodidad que menciona el libro.", "html": "Anota 3 señales de sinceridad y 3 de incomodidad que menciona el libro."}], "duracion": "<strong>Vídeo:</strong> ~9 min · <strong>Capítulo:</strong> ~25 min · <strong>Anotar:</strong> ~15 min", "como": "El orden entre vídeo y capítulo no importa; simplemente ten ambos vistos antes de escribir tus 6 ejemplos en la libreta.", "memoria": "Añade un segundo espacio conectado al primero y fija 10 loci nuevos ahí."}, {"id": "day-n2-s1d2", "label": "Sesión 10", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Mira primero los pies en 3 vídeos distintos de gente hablando de pie; anota hacia dónde apuntan.", "html": "Mira primero los pies en 3 vídeos distintos de gente hablando de pie; anota hacia dónde apuntan."}], "duracion": "~20 min", "como": "Busca en YouTube <strong>\"street interview\"</strong> o <strong>\"vox pop interview\"</strong> — vídeos cortos de gente de pie respondiendo preguntas en la calle, hay cientos. En cada uno fíjate primero en los pies antes que en la cara y anota hacia dónde apuntan: hacia el entrevistador (compromiso con la conversación), hacia un lado o la salida más cercana (deseo de irse, aunque siga hablando con educación), o cruzados entre sí (mayor comodidad relativa que separados). Son tendencias probabilísticas, no un detector de mentiras — apunta el patrón, no saques conclusiones todavía.", "memoria": "Recorre mentalmente la ruta completa (los 20 loci de ambas salas) en orden, todavía sin objetos."}, {"id": "day-n2-s2d1", "label": "Sesión 11", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Capítulo de \"El cuerpo habla\" sobre comportamientos pacificadores (cuello, cara, manos)", "html": "Capítulo de \"El cuerpo habla\" sobre comportamientos pacificadores (cuello, cara, manos)"}, {"tag": "Hacer", "text": "Anota las 5 formas de pacificación que describe el libro.", "html": "Anota las 5 formas de pacificación que describe el libro."}], "duracion": "<strong>Ver:</strong> ~25 min · <strong>Anotar:</strong> ~10 min", "como": "Las 5 formas de pacificación más citadas: tocarse o frotarse el cuello, ajustarse el cuello de la ropa, tocarse o morderse los labios, entrelazar los dedos con fuerza, y tocarse la cara (nariz, mejilla, oreja). Anótalas con un ejemplo mental de cuándo las has visto en ti mismo esta semana — reconocerlas en ti primero ayuda a detectarlas después en otros.", "memoria": "Coloca una lista nueva de 10 objetos en los loci de la primera sala."}, {"id": "day-n2-s2d2", "label": "Sesión 12", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Identifica 3 pacificadores en 3 vídeos de entrevistas o debates tensos; anota qué pregunta o tema los provocó.", "html": "Identifica 3 pacificadores en 3 vídeos de entrevistas o debates tensos; anota qué pregunta o tema los provocó."}], "duracion": "~20 min", "como": "Busca en YouTube <strong>\"awkward interview compilation\"</strong> o <strong>\"entrevista incómoda\"</strong> — hay compilaciones y entrevistas sueltas con preguntas que incomodan al entrevistado. Fíjate en estos pacificadores concretos: contacto con el cuello o la nuca · ajustarse el cuello de la ropa · tocarse o morderse los labios · entrelazar los dedos · tocarse la cara. Anota cuál aparece y en qué pregunta o tema exacto — el pacificador señala incomodidad o autocalma, no necesariamente mentira.", "memoria": "Recupera esos 10 objetos en orden desde la sala 1."}, {"id": "day-n2-s3d1", "label": "Sesión 13", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Tramo de 2 – Mentalismo sobre microexpresiones y rostro", "html": "Tramo de <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">2 – Mentalismo</a></em> sobre microexpresiones y rostro"}, {"tag": "Hacer", "text": "Elige 3 vídeos de entrevistas o debates tensos para el método silencioso de mañana.", "html": "Elige 3 vídeos de entrevistas o debates tensos para el método silencioso de mañana."}], "duracion": "<strong>Ver:</strong> ~15 min · <strong>Elegir vídeos:</strong> ~15 min", "como": "Busca en YouTube <strong>\"entrevista tensa\"</strong> o <strong>\"awkward interview compilation\"</strong> (la misma búsqueda de ayer sirve; elige 3 vídeos distintos a los que ya usaste en la Sesión 12) — cualquier entrevista con preguntas incómodas vale, no hace falta que sea de mentalismo.", "memoria": "Coloca otra lista de 10 objetos en los loci de la segunda sala."}, {"id": "day-n2-s3d2", "label": "Sesión 14", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Método silencioso: los 3 vídeos sin audio (2 min c/u), predice el estado emocional, verifica con audio.", "html": "Método silencioso: los 3 vídeos sin audio (2 min c/u), predice el estado emocional, verifica con audio."}], "duracion": "~60-90 min (3 vídeos × 2 min sin audio + repetición con audio + anotar)", "como": "Ya está pensado para hacerse 100% desde casa con los 3 vídeos que elegiste ayer — no necesitas salir. Para cada uno: míralo 2 min sin audio y anota qué crees que siente la persona usando palabras concretas (incomodidad, sorpresa, impaciencia, desinterés — evita \"algo raro\" o \"no sé, parece nervioso\"); luego actívalo con audio y comprueba si el contexto confirma o contradice tu lectura. Anota tu porcentaje de acierto de los 3.", "memoria": "Recupera esos 10 objetos en orden desde la sala 2."}, {"id": "day-n2-s4d1", "label": "Sesión 15", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Repasa tus notas de baseline en la libreta. Elige a una persona conocida para calibrar.", "html": "Repasa tus notas de baseline en la libreta. Elige a una persona conocida para calibrar."}], "duracion": "~20 min", "como": "Elige a alguien con quien ya hables regularmente esta semana — no hace falta que sea presencial, sirve una videollamada habitual.", "memoria": "Combina ambas salas: reparte 20 objetos nuevos, uno por locus, entre las dos."}, {"id": "day-n2-s4d2", "label": "Sesión 16", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Observa su comportamiento neutral 5 min; durante la semana, detecta 1 desviación real. Hito de nivel.", "html": "Observa su comportamiento neutral 5 min; durante la semana, detecta 1 desviación real. Hito de nivel."}], "duracion": "~5 min de observación directa + el resto de la semana en segundo plano", "como": "Una videollamada normal con esa persona vale igual — los gestos de comodidad se ven igual en pantalla que en persona.", "memoria": "Recupera los 20 objetos en orden — de momento sin cronómetro, prioriza la precisión."}], "checklist": ["Detecto gestos de pacificación sin pensarlo conscientemente, en conversación real", "Acierto el estado emocional en al menos 2 de 3 vídeos del método silencioso", "Tengo la línea base de al menos 2 personas cercanas anotada en mi libreta"], "milestone": "identificar un cambio de comodidad real en un vídeo mudo, sin depender del audio.", "simcards": []}, {"num": "03", "cat": "Comunicación", "name": "Estructura de Lectura en Frío", "objective": "dominar la estructura lingüística del cold reading — afirmaciones Barnum, treta arcoíris y bifurcación en tiempo real.", "sources": ["Ian Rowland — Cold Reading (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">3 — Mentalismo (NotebookLM, vídeo 8:17)</a>", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">4 — Mentalismo (NotebookLM, presentación)</a>"], "sessions": [{"id": "day-n3-s1d1", "label": "Sesión 17", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Vídeo 3 – Mentalismo (8:17) + capítulo de Rowland sobre afirmaciones Barnum", "html": "Vídeo <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">3 – Mentalismo</a></em> (8:17) + capítulo de Rowland sobre afirmaciones Barnum"}, {"tag": "Hacer", "text": "Escribe 10 afirmaciones Barnum propias (no copiadas del libro).", "html": "Escribe 10 afirmaciones Barnum propias (no copiadas del libro)."}], "duracion": "<strong>Vídeo:</strong> ~9 min · <strong>Capítulo:</strong> ~25 min · <strong>Escribir:</strong> ~20 min", "como": "Escribe cada frase con esta plantilla como base y cámbiala hasta que no se note el molde: «A veces [rasgo], aunque también hay momentos en que [rasgo opuesto] — sobre todo cuando [situación vaga, tipo ‘las cosas se complican’]». Ejemplo: «A veces te muestras muy seguro de ti mismo, pero también hay una parte que duda cuando de verdad importa». Cuantas más frases escribas con esa estructura, más rápido la interiorizas.", "memoria": "Repite el recorrido completo de las 2 salas con una lista nueva de 20 objetos, empezando a cronometrar cuánto tardas en colocarlos."}, {"id": "day-n3-s1d2", "label": "Sesión 18", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Prueba 3 de tus frases Barnum conmigo (Claude) y anota qué reacción te doy en cada una.", "html": "Prueba 3 de tus frases Barnum conmigo (Claude) y anota qué reacción te doy en cada una."}], "duracion": "~15 min", "como": "No necesitas hablar con nadie: ábreme en un chat y pégame \"Voy a decirte 3 frases tipo Barnum, una por una, como si te las dijera en una lectura. Después de cada una, reacciona como lo haría una persona real (de acuerdo, dudando, o corrigiendo algo) y al final dime cuál sonó más genérica y cuál más personalizada.\" Si otro día sí tienes con quién hablar, pruébalas también en persona — pero esto ya cuenta como sesión.", "memoria": "Recupera los 20 objetos en orden y anota tu tiempo total de recuperación."}, {"id": "day-n3-s2d1", "label": "Sesión 19", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Presentación 4 – Mentalismo + capítulo de Rowland sobre Treta Arcoíris y bifurcación", "html": "Presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">4 – Mentalismo</a></em> + capítulo de Rowland sobre Treta Arcoíris y bifurcación"}, {"tag": "Hacer", "text": "Anota la estructura de la Treta Arcoíris y de la bifurcación con tus propias palabras.", "html": "Anota la estructura de la Treta Arcoíris y de la bifurcación con tus propias palabras."}], "duracion": "<strong>Ver:</strong> ~30 min · <strong>Anotar:</strong> ~15 min", "como": "Coge una de tus frases Barnum de la Sesión 17 y divídela en sus dos mitades opuestas por separado (la Treta Arcoíris: primero afirmas un rasgo, luego su contrario, y observas cuál valida más la otra persona). Escribe 3 pares así en tu libreta — no hace falta decírselas a nadie todavía, solo tenerlas preparadas.", "memoria": "Repaso rápido de las 2 salas; ajusta cualquier locus que te cueste recordar antes de la prueba."}, {"id": "day-n3-s2d2", "label": "Sesión 20", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Practica bifurcar un rasgo + su opuesto conmigo (Claude), 2 veces con rasgos distintos.", "html": "Practica bifurcar un rasgo + su opuesto conmigo (Claude), 2 veces con rasgos distintos."}], "duracion": "~15 min", "como": "Ábreme y pégame: \"Te voy a decir un rasgo tipo Barnum con dos mitades opuestas (ej: 'a veces eres muy sociable, pero también necesitas tu espacio'). Reacciona validando con más énfasis una de las dos mitades sin decirme cuál — yo tengo que detectar cuál validaste más y seguir bifurcando por esa rama. Hazlo 2 veces con rasgos distintos y dime al final si acerté.\"", "memoria": "<strong>Hito (tras la sesión 20):</strong> memoriza y recupera 20 elementos en orden en menos de 5 minutos."}, {"id": "day-n3-s3d1", "label": "Sesión 21", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Capítulo de Rowland sobre la estructura completa de una lectura", "html": "Capítulo de Rowland sobre la estructura completa de una lectura"}, {"tag": "Hacer", "text": "Escribe el guion de una mini-lectura de 2 minutos.", "html": "Escribe el guion de una mini-lectura de 2 minutos."}], "duracion": "<strong>Ver:</strong> ~25 min · <strong>Escribir guion:</strong> ~20 min", "como": "Estructura mínima de una lectura de 2 minutos: 1) una frase Barnum de apertura (genérica, aplica a casi todos) · 2) una Treta Arcoíris sobre un tema emocional (trabajo, relaciones o dudas personales) · 3) una pregunta abierta para que la otra persona rellene con información real · 4) un cierre que suene específico usando lo que te acaba de decir. Escríbelo palabra por palabra la primera vez, luego lo naturalizas practicándolo.", "memoria": "Cambia los objetos cotidianos por elementos arbitrarios (números de 2 cifras, palabras sueltas o cartas de una baraja)."}, {"id": "day-n3-s3d2", "label": "Sesión 22", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Realiza la mini-lectura a un amigo o familiar (con consentimiento); al final, cuéntale la técnica usada. Hito de nivel.", "html": "Realiza la mini-lectura a un amigo o familiar (con consentimiento); al final, cuéntale la técnica usada. Hito de nivel."}], "duracion": "~20 min", "como": "Puedes hacerlo por videollamada si no coincides en persona con nadie — funciona igual de bien. Antes de empezar, dile a la otra persona que es una prueba de una técnica que estás aprendiendo. Sigue tu guion de la Sesión 21 pero deja hueco para improvisar sobre lo que te vaya respondiendo. Al terminar, cuéntale qué era cada frase (Barnum, arcoíris) y pregúntale cuál sintió más «personalizada» — esa es tu métrica de si funcionó.", "memoria": "Coloca 10 elementos arbitrarios en tus loci y recupéralos en orden."}], "checklist": ["Tengo un banco propio de 10 frases Barnum que no son las de ningún libro", "Consigo bifurcar una frase en plena conversación sin pausar el discurso", "He hecho al menos una mini-lectura completa y revelé la técnica al final"], "milestone": "construir una frase Barnum o Treta Arcoíris de forma fluida en conversación casual, sin cortar el ritmo del habla.", "simcards": [{"eyebrow": "Simulación con Claude · feedback real", "title": "Practica una lectura fría conmigo antes de hacerla con alguien real", "desc": "Esto es lo que te faltaba: alguien que te diga si tus frases Barnum sonaron genéricas o si de verdad conectaron. Ábreme en un chat (este mismo u otro nuevo) cuando termines el nivel y pégame exactamente esto:", "prompt": "Vamos a hacer una simulación de lectura fría. Haz de un desconocido con una historia inventada que yo no conozco (nombre, edad aproximada, un par de hechos de su vida — no me los digas). Yo te iré lanzando frases tipo Barnum o Treta Arcoíris y preguntas abiertas para intentar \"leerte\". Respóndeme como lo haría una persona real reaccionando a lo que le digo (afirmando, dudando, corrigiendo), sin decirme si he acertado hasta que yo escriba \"fin de la lectura\". Cuando lo escriba, sal del personaje y dame feedback: qué frases sonaron genéricas o forzadas, cuáles conectaron de verdad, y si en algún momento salté a una conclusión sin base real."}]}, {"num": "04", "cat": "Percepción", "name": "Lógica Inversa y Deducción", "objective": "construir hipótesis desde evidencia objetiva y eliminar el sesgo de confirmación en tus propias deducciones.", "sources": ["Cómo pensar como Sherlock Holmes — M. Konnikova (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">5 — Mentalismo (NotebookLM, vídeo 8:19)</a>", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">6 — Mentalismo (NotebookLM, presentación)</a>"], "sessions": [{"id": "day-n4-s1d1", "label": "Sesión 23", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Vídeo 5 – Mentalismo (8:19) + capítulo de Konnikova sobre atención plena", "html": "Vídeo <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">5 – Mentalismo</a></em> (8:19) + capítulo de Konnikova sobre atención plena"}, {"tag": "Hacer", "text": "Prepara el ejercicio de \"habitación de los sentidos\" para practicarlo a diario esta semana.", "html": "Prepara el ejercicio de \"habitación de los sentidos\" para practicarlo a diario esta semana."}], "duracion": "<strong>Vídeo:</strong> ~9 min · <strong>Capítulo:</strong> ~25 min · <strong>Preparar:</strong> ~10 min", "como": "Elige una habitación de tu casa que uses a diario. El ejercicio consiste en, durante 10 min cada día de la semana, sentarte ahí y nombrar mentalmente 5 cosas que ves, 4 que oyes, 3 que puedes tocar desde donde estás, 2 que hueles y 1 que saboreas — es la técnica clásica de anclaje sensorial 5-4-3-2-1, adaptada para entrenar atención plena antes de observar a otros.", "memoria": "Practica velocidad de codificación: coloca 10 elementos arbitrarios nuevos en menos de 10 segundos cada uno."}, {"id": "day-n4-s1d2", "label": "Sesión 24", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Practica 10 min el ejercicio de la \"habitación de los sentidos\". Repítelo cada día de la semana.", "html": "Practica 10 min el ejercicio de la \"habitación de los sentidos\". Repítelo cada día de la semana."}], "duracion": "10 min el ejercicio (repites a diario el resto de la semana, no solo hoy)", "como": "Es un ejercicio de atención plena que haces solo/a, en cualquier habitación de tu casa — no depende de salir ni de otras personas. Sigue el patrón 5-4-3-2-1 que preparaste ayer: 5 cosas que ves, 4 que oyes, 3 que tocas, 2 que hueles, 1 que saboreas. Repite los 10 minutos cada día de esta semana, no solo hoy — es la repetición la que entrena el músculo de la atención.", "memoria": "Recupera esos 10 elementos, revisa cuáles has fallado y repite solo esos loci."}, {"id": "day-n4-s2d1", "label": "Sesión 25", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Presentación 6 – Mentalismo + capítulo de Konnikova sobre el método de hipótesis múltiples", "html": "Presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">6 – Mentalismo</a></em> + capítulo de Konnikova sobre el método de hipótesis múltiples"}, {"tag": "Hacer", "text": "Anota en qué consiste el método de hipótesis múltiples de Holmes, con un ejemplo del libro.", "html": "Anota en qué consiste el método de hipótesis múltiples de Holmes, con un ejemplo del libro."}], "duracion": "<strong>Ver:</strong> ~30 min · <strong>Anotar:</strong> ~15 min", "como": "El método de hipótesis múltiples consiste en generar 3 explicaciones posibles antes de decidirte por una, para no caer en la primera que se te ocurra (que suele ser la más sesgada). Ejemplo: unas manchas de barro en los pantalones de alguien no significan automáticamente «ha ido de excursión» — podría ser jardinería, una obra cerca de casa, o lluvia y una acera rota. Anota el ejemplo con tus propias palabras y practica generando 3 hipótesis para algo que veas hoy mismo.", "memoria": "Sube a 20 elementos arbitrarios repartidos en las 2 salas, sin cronómetro, priorizando la precisión."}, {"id": "day-n4-s2d2", "label": "Sesión 26", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Ante 3 objetos de tu casa o 3 fotos de personas, genera 3 hipótesis distintas por cada uno antes de elegir la más probable.", "html": "Ante 3 objetos de tu casa o 3 fotos de personas, genera 3 hipótesis distintas por cada uno antes de elegir la más probable."}], "duracion": "~20 min", "como": "Usa objetos que ya tienes por casa (una mochila, un llavero, unos zapatos) o fotos de perfiles públicos que encuentres online — no necesitas a nadie delante.", "memoria": "Recupera los 20 y cuenta tus errores; repite el ejercicio completo con otra lista."}, {"id": "day-n4-s3d1", "label": "Sesión 27", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Capítulo de Konnikova sobre sesgos cognitivos", "html": "Capítulo de Konnikova sobre sesgos cognitivos"}, {"tag": "Hacer", "text": "Anota la diferencia entre el \"cerebro de Watson\" y el \"cerebro de Holmes\" que describe el libro.", "html": "Anota la diferencia entre el \"cerebro de Watson\" y el \"cerebro de Holmes\" que describe el libro."}], "duracion": "<strong>Ver:</strong> ~25 min · <strong>Anotar:</strong> ~15 min", "como": "El «cerebro de Watson» ve pero no observa: registra los datos sin conectar nada. El «cerebro de Holmes» observa activamente, comparando cada dato nuevo con lo que ya sabe y descartando lo irrelevante. Anota la diferencia con un ejemplo tuyo: algo que miraste hoy sin fijarte realmente (modo Watson) y algo que sí analizaste a fondo (modo Holmes).", "memoria": "Practica el repaso en dos pasadas: coloca 20 elementos y revisa una vez el recorrido entero antes de recuperar."}, {"id": "day-n4-s3d2", "label": "Sesión 28", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Registra 1 sesgo cognitivo propio detectado en tus deducciones de hoy (confirmación, anclaje, disponibilidad).", "html": "Registra 1 sesgo cognitivo propio detectado en tus deducciones de hoy (confirmación, anclaje, disponibilidad)."}], "duracion": "~10 min de reflexión al final del día", "como": "Repasa mentalmente tus decisiones del día antes de dormir y anota dónde metiste un atajo mental — no necesitas nada externo.", "memoria": "Recupera los 20 elementos; a los que falles, dales una imagen más exagerada y vuelve a probar solo esos."}, {"id": "day-n4-s4d1", "label": "Sesión 29", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Repasa tus notas de las sesiones anteriores. Elige a una persona real con objetos visibles (mochila, llavero, calzado).", "html": "Repasa tus notas de las sesiones anteriores. Elige a una persona real con objetos visibles (mochila, llavero, calzado)."}], "duracion": "~15 min", "como": "Puede ser alguien de tu casa, o tú mismo/a con tu propia mochila — el ejercicio de mañana funciona igual.", "memoria": "Simulacro cronometrado: coloca 20 elementos arbitrarios lo más rápido que puedas."}, {"id": "day-n4-s4d2", "label": "Sesión 30", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "A partir de 3 objetos de esa persona, construye una historia coherente y verifícala preguntando. Hito de nivel.", "html": "A partir de 3 objetos de esa persona, construye una historia coherente y verifícala preguntando. Hito de nivel."}], "duracion": "~30 min", "como": "Si no tienes a nadie disponible, hazlo con las pertenencias de un familiar que viva contigo y verifica preguntándole por la noche.", "memoria": "Recupera los 20 cronometrando el tiempo total y contando errores, como referencia antes del hito."}], "checklist": ["Genero 3 hipótesis antes de decidirme por una, de forma consistente", "Llevo un registro de al menos 10 sesgos propios detectados", "Mi deducción encadenada de 3 objetos fue confirmada como correcta al menos una vez"], "milestone": "explicar correctamente el origen de un objeto (desgaste, marca) sin haber preguntado nada.", "simcards": []}, {"num": "05", "cat": "Influencia", "name": "Persuasión y Palancas Cognitivas", "objective": "reconocer y aplicar de forma ética las palancas automáticas del comportamiento humano de Cialdini.", "sources": ["Influencia — Robert Cialdini (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">7 — Mentalismo (NotebookLM, vídeo 10:20)</a>", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">8 — Mentalismo (NotebookLM, presentación)</a>"], "sessions": [{"id": "day-n5-s1d1", "label": "Sesión 31", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Vídeo 7 – Mentalismo (10:20) + capítulos de Cialdini sobre Reciprocidad y Compromiso/Coherencia", "html": "Vídeo <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">7 – Mentalismo</a></em> (10:20) + capítulos de Cialdini sobre Reciprocidad y Compromiso/Coherencia"}, {"tag": "Hacer", "text": "Anota un ejemplo propio de reciprocidad y uno de compromiso/coherencia.", "html": "Anota un ejemplo propio de reciprocidad y uno de compromiso/coherencia."}], "duracion": "<strong>Vídeo:</strong> ~11 min · <strong>Capítulos:</strong> ~25 min · <strong>Anotar:</strong> ~10 min", "como": "Reciprocidad: la gente tiende a devolver un favor, por pequeño que sea. Compromiso/coherencia: una vez alguien se compromete con algo, aunque sea en voz baja, tiende a actuar de forma consistente con ello después. Anota un ejemplo real de cada uno — sirve algo tan simple como una muestra gratis en una tienda (reciprocidad) o decir en voz alta un objetivo delante de alguien (compromiso).", "memoria": "Último repaso de las 2 salas y de tus loci más débiles antes de la prueba."}, {"id": "day-n5-s1d2", "label": "Sesión 32", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Redacta un mensaje aplicando reciprocidad de forma ética (p. ej. a un cliente de Fiverr, real o hipotético).", "html": "Redacta un mensaje aplicando reciprocidad de forma ética (p. ej. a un cliente de Fiverr, real o hipotético)."}], "duracion": "~20 min", "como": "Es un mensaje escrito, no una conversación en vivo: si tienes un cliente activo en Fiverr, ofrécele por escrito algo pequeño de valor extra y observa cómo cambia su respuesta cuando conteste. Si no tienes ninguno activo, redacta igualmente el mensaje como si lo fueras a enviar, y si quieres una segunda opinión de si suena genuino o interesado, pégamelo aquí.", "memoria": "<strong>Hito (tras la sesión 32):</strong> 20 elementos arbitrarios recuperados en menos de 3 minutos, sin fallos."}, {"id": "day-n5-s2d1", "label": "Sesión 33", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Presentación 8 – Mentalismo + capítulos de Cialdini sobre Prueba Social y Autoridad", "html": "Presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">8 – Mentalismo</a></em> + capítulos de Cialdini sobre Prueba Social y Autoridad"}, {"tag": "Hacer", "text": "Anota un ejemplo propio de prueba social y uno de autoridad.", "html": "Anota un ejemplo propio de prueba social y uno de autoridad."}], "duracion": "<strong>Ver:</strong> ~30 min · <strong>Anotar:</strong> ~10 min", "como": "Prueba social: la gente copia lo que hace la mayoría, sobre todo en situaciones ambiguas (de ahí las reseñas, las colas, los «más vendidos»). Autoridad: seguimos más fácilmente a alguien con símbolos de estatus o conocimiento (bata blanca, título, cargo). Anota un ejemplo real de cada uno que hayas visto esta semana — en anuncios, en redes o en conversaciones.", "memoria": "Añade una tercera sala a tu palacio con 10–15 loci nuevos."}, {"id": "day-n5-s2d2", "label": "Sesión 34", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Identifica 3 usos de estos principios en publicidad o redes hoy y diseca su estructura por escrito.", "html": "Identifica 3 usos de estos principios en publicidad o redes hoy y diseca su estructura por escrito."}], "duracion": "~30 min", "como": "Se hace 100% desde el móvil, scrolleando anuncios o redes — no requiere salir de casa.", "memoria": "Recorre mentalmente el circuito de las 3 salas completo (30+ loci) en orden."}, {"id": "day-n5-s3d1", "label": "Sesión 35", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Capítulo de Cialdini sobre Escasez", "html": "Capítulo de Cialdini sobre Escasez"}, {"tag": "Hacer", "text": "Repasa los 6 principios completos y escribe tu guion de persuasión ética de 60 segundos.", "html": "Repasa los 6 principios completos y escribe tu guion de persuasión ética de 60 segundos."}], "duracion": "<strong>Ver:</strong> ~20 min · <strong>Escribir guion:</strong> ~20 min", "como": "Los 6 principios de Cialdini: reciprocidad, compromiso/coherencia, prueba social, autoridad, simpatía y escasez. Para tu guion de 60 segundos, elige solo uno o dos (mezclar los seis suena forzado) y aplícalos a algo real — por ejemplo, ofrecer un servicio de Fiverr usando escasez («solo tengo 2 huecos esta semana») combinado con prueba social («la mayoría de mis clientes repiten»). Escríbelo palabra por palabra.", "memoria": "Coloca una lista nueva de 15 elementos arbitrarios en los loci de la tercera sala."}, {"id": "day-n5-s3d2", "label": "Sesión 36", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Prueba tu guion de 60 segundos con una persona real. Hito de nivel.", "html": "Prueba tu guion de 60 segundos con una persona real. Hito de nivel."}], "duracion": "~15 min", "como": "Pruébalo con un cliente de Fiverr, un familiar, o grábate a ti mismo/a y evalúa si suena convincente. Antes de decir tu frase final, deja una pausa de 1-2 segundos tras mencionar la escasez o el principio que uses — ese silencio es lo que hace que la otra persona lo procese en vez de pasarlo por alto.", "memoria": "Recupera esos 15 elementos y repasa después el recorrido completo de las 3 salas de memoria."}], "checklist": ["He aplicado reciprocidad de forma consciente en una conversación real", "Puedo nombrar los 6 principios de Cialdini sin mirar el libro", "Probé mi guion de 60 segundos con al menos una persona real"], "milestone": "predecir la decisión de alguien antes de que ocurra, basándote en qué palanca de persuasión se le está aplicando.", "simcards": [{"eyebrow": "Simulación con Claude · feedback real", "title": "Practica aplicar (y detectar) los 6 principios de Cialdini conmigo", "desc": "Objetivo: usar un principio de persuasión de forma que se sienta natural, no manipuladora. Cuando termines el nivel, pégame esto:", "prompt": "Vamos a practicar persuasión ética. Ponme delante de una decisión pequeña e inventada que tengo que tomar (p. ej. elegir entre dos servicios, aceptar o no una propuesta) — invéntate los detalles y no me digas cuáles son mis dudas de antemano. Yo intentaré aplicarte un principio concreto de Cialdini (reciprocidad, escasez, autoridad, compromiso, simpatía o consenso social) para influir en tu decisión. Reacciona de forma realista: más receptivo si el intento tiene sentido para tu personaje, más reticente si se nota forzado o manipulador. Cuando yo escriba \"fin\", sal del personaje y dime: qué principio detectaste que estaba usando, si se sintió genuino o manipulador, y qué habría hecho que sonara más natural."}]}, {"num": "06", "cat": "Influencia", "name": "Sugestión y Forzado Psicológico", "objective": "rapport instantáneo, lenguaje ericksoniano, priming y forzado psicológico sutil — el nivel más avanzado y el que exige más cuidado ético (ver sección de ética antes de empezar).", "sources": ["Banachek — Psychological Subtleties (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">9 — Mentalismo (NotebookLM, vídeo 8:01)</a>", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">10 — Mentalismo (NotebookLM, presentación)</a>", "De Sapos a Príncipes — Bandler/Grinder (PDF)", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">11 — Mentalismo (NotebookLM, vídeo 7:58)</a>", "<a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">12 — Mentalismo (NotebookLM, presentación)</a>"], "sessions": [{"id": "day-n6-s1d1", "label": "Sesión 37", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Ver", "text": "Vídeo 9 – Mentalismo (8:01)", "html": "Vídeo <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">9 – Mentalismo</a></em> (8:01)"}, {"tag": "Hacer", "text": "Anota en qué consiste el reflejo corporal y vocal (mirroring).", "html": "Anota en qué consiste el reflejo corporal y vocal (mirroring)."}], "duracion": "<strong>Ver:</strong> ~10 min · <strong>Anotar:</strong> ~10 min", "como": "El reflejo corporal y vocal (mirroring) consiste en igualar sutilmente el ritmo de habla, el volumen, la postura o los gestos de la otra persona — no imitarla de forma obvia, sino acercarte a su «frecuencia» para generar comodidad inconsciente. Anota con tus propias palabras en qué se diferencia de la imitación evidente, que genera rechazo en vez de rapport.", "memoria": "Añade una cuarta sala con el resto de loci hasta llegar a 40+ puntos fijos en total."}, {"id": "day-n6-s1d2", "label": "Sesión 38", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Practica mirroring por sombra con 3 fragmentos de vídeo, sin que nadie te vea.", "html": "Practica mirroring por sombra con 3 fragmentos de vídeo, sin que nadie te vea."}], "duracion": "~20 min", "como": "Busca en YouTube <strong>\"TED talk\"</strong> (cualquier charla completa vale, elige una persona expresiva) y, mirándote en el reflejo de la pantalla o grabándote con el móvil, iguala en tiempo real: ritmo de habla (rápido/lento) · volumen relativo · postura general · gestos de manos más repetidos · expresión facial de base. Repite con 3 fragmentos de 2-3 min de charlas distintas — es \"mirroring de sombra\", entrenas el músculo sin que nadie tenga que estar delante.", "memoria": "Recorre mentalmente las 4 salas completas en orden, sin objetos todavía."}, {"id": "day-n6-s2d1", "label": "Sesión 39", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Vídeo 11 – Mentalismo (7:58)", "html": "Vídeo <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">11 – Mentalismo</a></em> (7:58)"}, {"tag": "Hacer", "text": "Anota 3 ejemplos de presuposiciones que menciona.", "html": "Anota 3 ejemplos de presuposiciones que menciona."}], "duracion": "<strong>Ver:</strong> ~10 min · <strong>Anotar:</strong> ~15 min", "como": "Una presuposición da por hecho algo dentro de la frase, sin decirlo directamente — la persona tiene que aceptar ese hecho implícito para poder responder. Ejemplo: «cuando decidas cuál prefieres» da por hecho que va a decidir, no si va a decidir. Anota los 3 ejemplos del vídeo y fíjate en qué da por hecho cada uno.", "memoria": "Aprende la asociación nombre–cara: elige un rasgo facial distintivo como “gancho” para 10 nombres (fotos, vídeos o personas reales)."}, {"id": "day-n6-s2d2", "label": "Sesión 40", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Construye 5 frases con presuposiciones (\"cuando decidas cuál prefieres...\") y pruébalas por escrito.", "html": "Construye 5 frases con presuposiciones (\"cuando decidas cuál prefieres...\") y pruébalas por escrito."}], "duracion": "~15 min", "como": "No hace falta hablar con nadie: úsalas en un mensaje de texto, un comentario en redes, o una respuesta a un chat de soporte/cliente. Si hoy no tienes a quién escribírselas, dímelas a mí en el chat y te digo si suenan naturales o forzadas.", "memoria": "Recupera los 10 nombres a partir solo de las caras, sin mirar la lista."}, {"id": "day-n6-s3d1", "label": "Sesión 41", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Repasa el tramo final de 11 – Mentalismo + presentación 12 – Mentalismo (patrones por tipo)", "html": "Repasa el tramo final de <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">11 – Mentalismo</a></em> + presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">12 – Mentalismo</a></em> (patrones por tipo)"}, {"tag": "Hacer", "text": "Anota qué es el priming y un ejemplo de cómo sembrar un concepto.", "html": "Anota qué es el priming y un ejemplo de cómo sembrar un concepto."}], "duracion": "<strong>Ver:</strong> ~20 min · <strong>Anotar:</strong> ~15 min", "como": "El priming consiste en sembrar una palabra o idea de forma neutra para que reaparezca de forma espontánea más tarde en la conversación de la otra persona, sin que lo note. Ejemplo: si mencionas de pasada «el mar» varias veces al principio de una charla, es más probable que la otra persona use palabras relacionadas (playa, verano, vacaciones) más tarde. Anota el ejemplo del vídeo con tus propias palabras.", "memoria": "Combina nombres y caras con tu palacio: coloca 10 pares nombre–cara en los loci de una de tus salas."}, {"id": "day-n6-s3d2", "label": "Sesión 42", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Siembra un concepto neutro al inicio de una charla; observa si reaparece espontáneamente 10 min después.", "html": "Siembra un concepto neutro al inicio de una charla; observa si reaparece espontáneamente 10 min después."}], "duracion": "~15 min de siembra + revisión a los 10 min", "como": "Una llamada o chat largo con alguien vale igual, no necesita ser presencial. Después de sembrar el concepto, cambia de tema deliberadamente durante unos minutos antes de volver cerca de esa zona — si reaparece la palabra o idea sin que tú la reintroduzcas, el priming ha funcionado.", "memoria": "Recupera esos 10 pares nombre–cara desde los loci correspondientes."}, {"id": "day-n6-s4d1", "label": "Sesión 43", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Presentación 10 – Mentalismo (playbook de calibración y forzado)", "html": "Presentación <em><a href=\"https://notebooklm.link.google/CCPvbSel5DNS\" rel=\"noopener\" target=\"_blank\">10 – Mentalismo</a></em> (playbook de calibración y forzado)"}, {"tag": "Hacer", "text": "Anota los 2-3 patrones de forzado que más te convenzan del playbook.", "html": "Anota los 2-3 patrones de forzado que más te convenzan del playbook."}], "duracion": "<strong>Ver:</strong> ~25 min · <strong>Anotar:</strong> ~15 min", "como": "Repasa el playbook y anota los 2-3 patrones de forzado que te resulten más naturales a ti — no los que más te gusten en teoría, sino los que de verdad podrías decir sin que suene ensayado. Escribe cada uno con un ejemplo de frase real que usarías.", "memoria": "Prepara la prueba mixta: reparte 40+ elementos (objetos + nombres/caras) entre las 4 salas."}, {"id": "day-n6-s4d2", "label": "Sesión 44", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Practica un forzado entre 2 opciones conmigo (Claude), 5 rondas seguidas; registra tu tasa de éxito.", "html": "Practica un forzado entre 2 opciones conmigo (Claude), 5 rondas seguidas; registra tu tasa de éxito."}], "duracion": "~20 min", "como": "Ábreme y pégame: \"Vamos a hacer 5 rondas de un forzado entre dos opciones. En cada ronda, dame dos opciones de forma que una parezca más natural que la otra (el forzado), sin que sea obvio cuál prefieres que elija. Yo elijo una y tú anotas si fue la que buscabas — repetimos 5 veces con forzados distintos y al final me dices mi tasa de éxito.\"", "memoria": "<strong>Hito (tras la sesión 44):</strong> recupera los 40+ elementos, incluidos nombres y caras, en orden por sala."}, {"id": "day-n6-s5d1", "label": "Sesión 45", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Ver", "text": "Relee el Código de Práctica Ética completo (sección dedicada de este plan) antes de seguir.", "html": "Relee el Código de Práctica Ética completo (sección dedicada de este plan) antes de seguir."}], "duracion": "~5 min de lectura — tómate el resto para pensar en cómo aplicarás cada punto en tus prácticas de esta semana, no hace falta estirarlo", "como": "Antes de seguir con estas dos últimas sesiones del nivel, dedica los 5 minutos a releer el Código de Práctica Ética completo (sección dedicada de este plan) — es corto, pero es la parte que marca la diferencia entre practicar mentalismo y hacer algo que incomode o dañe a alguien de verdad.", "memoria": "Reserva una “sala de lectura” dedicada del palacio para tu práctica de esta semana."}, {"id": "day-n6-s5d2", "label": "Sesión 46", "tag": "Rápida", "tagClass": ["sess-tag", "rapida"], "steps": [{"tag": "Hacer", "text": "Revisa en qué momentos de las sesiones de este nivel cruzaste o respetaste esos límites; escribe tu conclusión. Hito de nivel.", "html": "Revisa en qué momentos de las sesiones de este nivel cruzaste o respetaste esos límites; escribe tu conclusión. Hito de nivel."}], "duracion": "~20 min de reflexión escrita", "como": "Repasa mentalmente (o en tu libreta) cada sesión de este nivel: mirroring, presuposiciones, priming, forzado. Para cada una, pregúntate si en algún momento la usaste para algo que la otra persona no habría aceptado de saberlo. Escribe una conclusión honesta de una o dos frases — es el hito que cierra el nivel más delicado del programa.", "memoria": "Tras cada conversación de práctica, guarda 3–5 datos revelados por la otra persona en esa sala nada más terminar."}], "checklist": ["Mi mirroring no ha sido percibido como imitación evidente por nadie", "He registrado la tasa de éxito de al menos 5 forzados de elección", "He revisado el código ético y puedo justificar cada técnica que uso"], "milestone": "guiar la elección de una persona entre dos opciones concretas usando anclaje o forzado sutil, de forma reproducible.", "simcards": [{"eyebrow": "Simulación con Claude · feedback real", "title": "Practica rapport y un forzado sutil conmigo", "desc": "Aquí es donde más se nota si el forzado suena natural o cantoso. Cuando termines el nivel, pégame esto:", "prompt": "Vamos a practicar rapport y forzado sutil. Haz de una persona cualquiera en una conversación informal (invéntate su humor y tono, no me lo digas). Yo intentaré generar rapport contigo (igualando tu ritmo y forma de hablar) y en algún momento intentaré guiarte hacia una de dos opciones concretas usando anclaje o presuposición, sin que sea obvio. Reacciona de forma natural: más cómodo si conecto bien, más distante o desconfiado si fuerzo la sincronía o el forzado se nota. Cuando yo escriba \"fin\", sal del personaje y dime: en qué momentos notaste que conectaba de verdad, cuándo se sintió forzado, y si detectaste hacia qué opción te estaba guiando y en qué momento."}]}, {"num": "07", "cat": "Integración — nivel nuevo", "name": "Rutina de Mentalismo en Vivo", "objective": "Por qué se añade: tu plan original saltaba directo del Palacio de la Memoria a \"1–3 años de maestría de campo\" sin un puente concreto. Este nivel obliga a combinar los seis anteriores en una sola pieza ensayable antes de soltarte a la práctica libre indefinida.", "sources": ["Síntesis de niveles 1–6", "Tu propia libreta de notas Cornell"], "sessions": [{"id": "day-n7-s1d1", "label": "Sesión 47", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Ver", "text": "Tus checklists marcadas de los niveles 1–6, en esta misma página", "html": "Tus checklists marcadas de los niveles 1–6, en esta misma página"}, {"tag": "Hacer", "text": "Elige qué técnica de cada nivel va a incluirse en tu rutina.", "html": "Elige qué técnica de cada nivel va a incluirse en tu rutina."}], "duracion": "<strong>Ver:</strong> ~15 min · <strong>Elegir:</strong> ~15 min", "como": "Repasa las checklists marcadas de los 6 niveles anteriores en esta misma página. Por cada nivel, elige la técnica que mejor te salió o con la que más cómodo te sientes — esa es la que vas a incluir en tu rutina de 8-10 minutos, no hace falta meterlo todo.", "memoria": "Repite el hábito de guardar 3–5 datos revelados en la sala de lectura durante tus prácticas de esta semana."}, {"id": "day-n7-s1d2", "label": "Sesión 48", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Diseña por escrito una rutina de 8–10 min: observación → cold reading → forzado → cierre.", "html": "Diseña por escrito una rutina de 8–10 min: observación → cold reading → forzado → cierre."}], "duracion": "~60-90 min", "como": "Estructura sugerida de 8-10 minutos: 1) Observación inicial (~1 min) — barrido de 6 segundos + 2-3 hechos objetivos en voz alta o mental · 2) Cold reading (~3 min) — 2-3 frases Barnum/Treta Arcoíris + una pregunta abierta de elicitación · 3) Forzado (~2 min) — guía la elección entre dos opciones con anclaje o presuposición · 4) Cierre (~2 min) — una «revelación» que conecte lo observado con lo dicho, y si preguntan, explica la técnica. Escríbelo con tus propias palabras exactas, no solo la estructura.", "memoria": "Haz una recuperación de 2 minutos de esos datos sin consultar tu libreta, al final del día."}, {"id": "day-n7-s2d1", "label": "Sesión 49", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Ensaya la rutina en solitario en voz alta 2 veces, cronometrando.", "html": "Ensaya la rutina en solitario en voz alta 2 veces, cronometrando."}], "duracion": "~30 min", "como": "En tu habitación, en voz alta, delante del espejo o grabándote con el móvil. Cronometra las dos veces — si te pasas mucho de los 8-10 minutos, corta la parte que más se alargue (normalmente el cold reading) en vez de recortar el cierre, que es lo que más impacto deja.", "memoria": "Ensayo general: en una conversación o lectura simulada, guarda en vivo los nombres y datos revelados en la sala de lectura."}, {"id": "day-n7-s2d2", "label": "Sesión 50", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Ejecuta la rutina con 1–2 personas reales; pide feedback honesto y revela algo de la técnica si preguntan.", "html": "Ejecuta la rutina con 1–2 personas reales; pide feedback honesto y revela algo de la técnica si preguntan."}], "duracion": "~20-30 min", "como": "Puede ser por videollamada si no coincides en persona con nadie — la rutina entera es adaptable a formato remoto. Al terminar, antes de revelar nada, pregunta primero: «¿qué es lo que más te ha sorprendido?» — así consigues feedback genuino antes de que sepan cómo se hizo. Luego, si preguntan, explica la técnica como dice el código ético.", "memoria": "Recupera sin notas todo lo guardado esta semana, como simulacro final antes del hito."}, {"id": "day-n7-s3d1", "label": "Sesión 51", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Ajusta el guion según el feedback recibido.", "html": "Ajusta el guion según el feedback recibido."}], "duracion": "~30 min", "como": "Con el feedback de la Sesión 50 delante, identifica qué parte sonó más forzada o menos convincente y reescribe solo esa parte — no hace falta rehacer el guion entero. Si el feedback fue sobre todo positivo, ajusta igualmente el timing o el orden de las frases para que fluya mejor.", "memoria": "Revisa mentalmente tu sala de lectura, vacía y lista, antes de tu lectura real de cierre."}, {"id": "day-n7-s3d2", "label": "Sesión 52", "tag": "Larga", "tagClass": ["sess-tag", "larga"], "steps": [{"tag": "Hacer", "text": "Graba la rutina completa en vídeo; evalúala contra las checklists de los niveles 1–6. Hito de nivel.", "html": "Graba la rutina completa en vídeo; evalúala contra las checklists de los niveles 1–6. Hito de nivel."}], "duracion": "~20-30 min", "como": "Graba con el móvil apoyado contra algo o con alguien sujetándolo — no hace falta equipo profesional. Al revisar la grabación, ve checklist por checklist de cada nivel (1 al 6) y marca honestamente cuáles cumples ya de forma natural y cuáles todavía se notan forzados — esa lista es tu hoja de ruta para la fase de maestría que empieza después.", "memoria": "<strong>Hito (tras la sesión 52):</strong> en una lectura real, guarda y recupera de memoria los nombres y datos revelados, sin usar notas."}], "checklist": ["Tengo una rutina de 8–10 minutos escrita, no improvisada", "La he ejecutado sin notas frente a al menos 3 personas", "Tengo la grabación revisada y una lista de qué ajustar"], "milestone": "ejecutar la rutina completa sin notas, con reacción positiva de al menos 2 de 3 espectadores. Al superarlo, entras en fase de maestría.", "simcards": [{"eyebrow": "Simulación con Claude · el gran ensayo", "title": "Ensaya la lectura completa conmigo antes de hacerla con gente real", "desc": "Esta junta todo el programa: observación, Barnum, calibración, elicitación y tu Palacio de la Memoria en vivo. Úsala como ensayo antes del hito de arriba. Pégame esto:", "prompt": "Esta es la simulación grande de cierre. Haz de un desconocido con una historia de vida inventada y detallada (trabajo, una preocupación actual, una relación importante) que no me reveles. Yo voy a intentar una lectura completa combinando observación, frases Barnum, calibración de tus reacciones y algo de elicitación, e iré guardando en mi Palacio de la Memoria lo que vayas revelando. Al final, sin mirar notas, voy a intentar recitarte lo que dijiste. Cuando yo escriba \"fin de la lectura\", sal del personaje y dame feedback honesto: qué acerté, qué fue genérico, dónde fui demasiado rápido a una conclusión, y si mi recuerdo de lo que dijiste fue preciso."}]}], "memoria": {"lede": ["<strong>Cambio clave frente a tu plan original:</strong> en vez de un bloque aislado al final (antiguo Bloque 6), la memoria se entrena ~15 min en cada sesión desde la primera — porque te sirve desde el primer día para retener lo que observas en los otros niveles.", "<strong>Fuente principal de esta pista:</strong> los ~15 min de cada sesión siguen, en orden, el <a href=\"https://artofmemory.com/blog/free-memory-course/\" rel=\"noopener\" target=\"_blank\">Free Memory Course de Art of Memory</a> — un curso gratuito real (sin pago, sin prueba de tarjeta, incluye su ebook <em>\"Learn the Art of Memory\"</em>), de la comunidad de memoria competitiva más reputada en abierto. Es el único de los cursos que busqué que resultó ser gratis de verdad y no un \"audit\" de Coursera que en realidad pide tarjeta o pago — así que aquí sí sustituye a cualquier fuente genérica como base de la técnica."], "steps": [{"when": "TRAS LA SESIÓN 8", "text": "Palacio de una sola habitación. Memorizas y recuperas 10 elementos en orden. <em>(Curso: pasos 1-4 — fundamentos, story &amp; linking, peg list del alfabeto, método de loci.)</em>"}, {"when": "TRAS LA SESIÓN 20", "text": "Palacio de 2 habitaciones. 20 elementos en orden, en menos de 5 minutos. <em>(Curso: paso 5 — trucos avanzados de palacio.)</em>"}, {"when": "TRAS LA SESIÓN 32", "text": "20 elementos arbitrarios recuperados en menos de 3 minutos, sin fallos. <em>(Curso: paso 7 — sistema mayor para convertir números en imágenes.)</em>"}, {"when": "TRAS LA SESIÓN 44", "text": "Palacio multi-sala (3–4 espacios). 40+ elementos, incluyendo nombres y caras de personas con quienes practicas lectura en frío. <em>(Curso: paso 6 — memorización de nombres y caras.)</em>"}, {"when": "TRAS LA SESIÓN 52", "text": "Usas el palacio en una lectura real para recordar nombres y datos revelados por el interlocutor, sin notas."}]}, "etica": ["<strong>Contexto social, no decisiones importantes de terceros.</strong> Practica en conversación casual — nunca para influir decisiones financieras, médicas o legales de otra persona.", "<strong>Transparencia cuando se te pregunte.</strong> Si alguien pregunta cómo lo hiciste, explícaselo. El mentalismo pierde su valor si se confunde con manipulación encubierta permanente.", "<strong>Consentimiento implícito del entorno social.</strong> Practica con personas que ya saben que estás aprendiendo esto, no con desconocidos vulnerables.", "<strong>Nunca con menores sin supervisión de un adulto presente.</strong>", "<strong>El objetivo es la lectura, no el engaño con daño.</strong> Si una técnica solo funciona explotando el miedo o la vulnerabilidad de alguien, no es una técnica que quieras dominar."], "maestria": {"lede": "Al superar el Nivel 7 tienes el 100% de la arquitectura teórica. Lo que falta para llegar a la soltura de Patrick Jane son las horas acumuladas de práctica social real — se estima entre 1 y 3 años. Las mismas 4h/semana, reorganizadas:", "tiles": [{"h": "BLOQUE 1", "v": "2h", "p": "Práctica social real: clientes de Fiverr, amigos, eventos — aplicación en contexto real, no ejercicio aislado."}, {"h": "BLOQUE 2", "v": "1h", "p": "Repaso rotativo: cada semana revisitas uno de los 7 dominios para que ninguno se oxide."}, {"h": "BLOQUE 3", "v": "30 min", "p": "Actualizas el Palacio de la Memoria con información nueva relevante de tu semana."}, {"h": "BLOQUE 4", "v": "30 min", "p": "Registro en libreta + revisión mensual dentro de tu tracker de hábitos ya existente."}], "review": "Cada 3 meses en fase de maestría, graba una nueva rutina de mentalismo y compárala con la anterior. Es tu única métrica de progreso a largo plazo — el resto es acumulación silenciosa de horas."}, "habitos": [{"name": "Disparador del móvil", "text": "Cada vez que abras Instagram, YouTube o X, obsérvate obligado a mirar solo los zapatos o las manos de la primera persona que aparezca, 3 segundos, antes de consumir el contenido."}, {"name": "Disparador de la puerta", "text": "Al cruzar el pomo de una estancia, pausa 1 segundo y nombra mentalmente dos hechos objetivos del entorno (\"cable negro en el suelo\", \"sombra en la esquina izquierda\")."}, {"name": "Disparador de la espera", "text": "En una cola o el transporte, dedica ese tiempo muerto a un barrido completo de una persona a distancia segura: postura, calzado, objetos, desgaste."}, {"name": "Disparador nocturno", "text": "Antes de dormir, repasa mentalmente en 60 segundos lo guardado hoy en el Palacio de la Memoria. Es la repetición espaciada que hace que el palacio no se olvide."}], "objTable": [["\"Parece nervioso y sospechoso\"", "Fricción constante del cuello + pies apuntando a la salida", "Deseo de huida por sobrecarga de tensión o prisa física"], ["\"Es una persona muy elegante\"", "Zapatos de piel con desgaste exclusivo en el tacón derecho", "Conduce largas distancias de forma habitual (apoyo de talón)"], ["\"Está ocultando algo en el móvil\"", "Pantalla girada hacia abajo + reajuste del teléfono al sonar", "Búsqueda activa de privacidad visual inmediata"], ["\"No le importa nada su aspecto\"", "Misma prenda con manchas repetidas en tres días distintos", "Prioridad cognitiva desplazada hacia otra urgencia (no indiferencia)"]]};